corrected_code:
const formidable = require('formidable');

router.post('/academic/submissions/:submissionId/final-draft', authenticateStudent, (req, res) => {
  const { submissionId } = req.params;
  const form = new formidable.IncomingForm();

  form.parse(req, async (err, fields, files) => {
    const submission = await db.query(
      'SELECT id FROM thesis_submissions WHERE id = $1 AND student_id = $2',
      [submissionId, req.user.studentId]
    );
    if (submission.rowCount === 0) {
      return res.status(403).json({ error: 'Access denied: submission does not belong to you' });
    }

    const destPath = `/srv/theses/${submissionId}_final.pdf`;
    fs.copyFileSync(files.thesisPdf.filepath, destPath);

    await db.query(
      'UPDATE thesis_submissions SET file_path = $1, submitted_at = NOW() WHERE id = $2',
      [destPath, submissionId]
    );
    res.json({ success: true, submissionId });
  });
});
